oxy_webhelp_navlinks = {"arch_protect_data_archival_locations-d39536e9327":{"topics":[{"title":"Configuring an archival policy","shortdesc":"<p class=\"shortdesc\">When you create or edit a custom SLA Domain, configure the archival policy for the         SLA Domain to define which snapshots to archive, the archive schedule, and the archival         location.<\/p>","href":"saas\/configuring_archival_policy_2.html","attributes":{"data-id":"configuring_archival_policy"},"menu":{"hasChildren":false},"tocID":"configuring_archival_policy-d39536e9338","topics":[]},{"title":"Creating a custom SLA Domain","shortdesc":"<p class=\"shortdesc\">Create a custom SLA Domain to define and customize workload protection and management         policies.<\/p>","href":"saas\/rsc_creating_custom_sla_domain_2.html","attributes":{"data-id":"rsc_creating_custom_sla_domain"},"menu":{"hasChildren":false},"tocID":"rsc_creating_custom_sla_domain-d39536e9349","topics":[]},{"title":"Instant tiering of snapshots","shortdesc":"<p class=\"shortdesc\">The instant tiering feature archives data immediately to the specified cold storage         tier in the cloud. This approach is ideal for optimizing storage costs when data restoration         is a rare requirement.<\/p>","href":"archival\/arch_instant_tiering_snapshots.html","attributes":{"data-id":"arch_instant_tiering_snapshots"},"menu":{"hasChildren":false},"tocID":"arch_instant_tiering_snapshots-d39536e9360","next":"arch_instant_tiering_snapshots-d39536e9360"},{"title":"Upload of downloaded snapshots to archival locations","shortdesc":"<p class=\"shortdesc\">Rubrik can upload a snapshot that was previously downloaded from an archival location         or a replication target to a different archival location. Normally, Rubrik does not         re-archive a downloaded snapshot. With this capability, you can upload it on demand by         using a separate SLA Domain that you specify.<\/p>","href":"archival\/upload_downloaded_snapshots.html","attributes":{"data-id":"upload_downloaded_snapshots"},"menu":{"hasChildren":false},"tocID":"upload_downloaded_snapshots-d39536e9382","topics":[]}]}};